shaderSource:
uniform float2 resolution;
uniform float tiltX;
uniform float tiltY;

half4 main(float2 xy) {
  float2 uv = xy / max(resolution, float2(1.0, 1.0));
  float aspect = resolution.x / max(resolution.y, 1.0);
  float2 key = float2(0.22, 0.12) + float2(tiltX, tiltY) * 0.14;

  float2 d = uv - key;
  d.x *= aspect;
  float keyLight = exp(-dot(d, d) * 1.8);

  float vignette = pow(length((uv - float2(0.5, 0.55)) * float2(1.15, 1.0)), 1.6);
  vignette = smoothstep(0.15, 1.05, vignette);

  float floorGlow = exp(-pow((uv.y - 0.78) * 3.2, 2.0)) * 0.22;
  float haze = (1.0 - uv.y) * 0.12;

  half3 cool = half3(0.35, 0.48, 0.72);
  half3 warm = half3(0.55, 0.42, 0.32);
  half3 tint = mix(cool, warm, clamp(uv.x * 0.35 + (1.0 - uv.y) * 0.25, 0.0, 1.0));

  float alpha = keyLight * 0.34 + haze + floorGlow;
  alpha *= (1.0 - vignette * 0.55);
  alpha = clamp(alpha, 0.0, 0.55);

  return half4(tint, alpha);
}
